package com.kitchenos.connect.ui;
/** Preparation, processing and result cues; no unverified automatic cooking claims. */
public final class FunctionGuidance {
 public static String[] get(String id){switch(id){
  case "manual":return new String[]{"Zeit, Temperatur und Bewegung für dein Rezept selbst einstellen.","Passendes Werkzeug bei Stillstand einsetzen. Zutaten in den Mixtopf geben und die maximale Füllmarkierung beachten.","Die drei Kreise stellen Zeit, Temperatur und Stufe ein. Das Symbol im Stufenkreis wechselt zwischen Messer und Rühren.","Bis 150 °C und Stufe 10 einstellbar. Bei Ziel- oder Topftemperatur über 80 °C höchstens Stufe 6. Für 180 °C die Funktion Anbraten verwenden.","Nach dem Lauf Konsistenz und Garzustand prüfen. Vor dem Öffnen den Messerstillstand abwarten."};
  case "stir":return new String[]{"Mit der Messerabdeckung schonend in ausreichend Flüssigkeit rühren.","Messerabdeckung bei Stillstand sicher auf das Messer setzen. Die Darstellung zeigt das gewählte Zubehör; sie erkennt nicht, ob es tatsächlich eingesetzt ist.","Für dieses Zubehör höchstens Stufe 1 und 100 °C wählen. Nicht trocken erhitzen.","Zum Vermengen ohne Abdeckung das manuelle Rückwärtsrühren verwenden. Der Aufschlagbesen gehört zur Funktion Schlagen.","Vor dem Entnehmen von Zubehör den vollständigen Stillstand abwarten."};
  case "water":return new String[]{"Klares Wasser ohne Messerbewegung erhitzen.","Trinkwasser einfüllen. Mindestmenge, Füllmarkierung und Deckelstellung aus der Geräteanleitung beachten.","Zieltemperatur passend zur Verwendung wählen und bewusst starten. Bei Erreichen der Temperatur wird gestoppt; das interne Zeitlimit beendet einen zu langen Aufheizversuch.","Beim Öffnen und Ausgießen Abstand zu heißem Dampf halten."};
  case "fry":return new String[]{"Zwiebelstreifen und andere passende Zutaten mit etwas Fett anbraten.","Zwiebeln in Streifen schneiden und mit geeignetem Fett in den Mixtopf geben. Keinen Rühraufsatz verwenden und den Topf nicht leer trocken aufheizen.","Mit 5 Minuten bei 140 °C beginnen. Rückwärts auf Stufe 1: 3 Sekunden Rühren / 10 Sekunden Pause, 5 / 25 oder durchgehend. In den automatischen Rührpausen steht nur das Messer still; der Heizauftrag bleibt aktiv. Stoppen beendet den gesamten Lauf. Die Stufe zeigt die Programmvorgabe, keine gemessene Drehzahl. Nach gestopptem Lauf die Bräunung prüfen und bei Bedarf kurz verlängern.","Kleine Mengen bräunen gleichmäßiger; bei Bedarf portionsweise arbeiten. Der Sollwert wird am Topfboden erfasst und ist nicht die genaue Temperatur jeder Zwiebel."};
  case "whip":return new String[]{"Kalte Sahne mit dem Rühraufsatz luftig aufschlagen.","Kalten Topf verwenden, Rühraufsatz fest auf das Messer setzen. Gut gekühlte Sahne einfüllen und Deckel schließen.","Ohne Heizung mit 1 Minute auf Stufe 3 beginnen. Regelmäßig kontrollieren: Menge und Fettgehalt verändern die nötige Zeit.","Bei gewünschter Festigkeit stoppen; zu langes Schlagen trennt die Sahne. Aufsatz erst bei Stillstand abnehmen."};
  case "clean":return new String[]{"Fünf Reinigungsprogramme für unterschiedliche Rückstände.","Grobe Reste und alle Aufsätze entfernen. 500 ml bis höchstens 1 l Wasser einfüllen. Deckel und Messbecher einsetzen.","Kurz, Teig, Basis, Fett / Karamell oder Reinigung+ bewusst auswählen und starten. Details bei ⓘ. Teig mit kaltem Wasser; heiße Programme zunächst nur mit Wasser testen. Bei Schaum stoppen.","Stillstand abwarten, heißes Wasser vorsichtig ausgießen und klar nachspülen. Anhaftende Reste von Hand nachreinigen."};
  case "mix":return new String[]{"Flüssigkeiten und weiche Lebensmittel glatt vermischen.","Obst in Stücke schneiden, mit Flüssigkeit in den Mixtopf geben und Deckel schließen. Vor hohen Stufen einen eingesetzten Rühraufsatz entfernen.","Mit 30 Sekunden auf Messerstufe 5 beginnen. Für ein gröberes Ergebnis niedriger einstellen, für ein feineres Ergebnis kurz nachmixen.","Bei Stillstand Konsistenz prüfen und bei Bedarf Flüssigkeit ergänzen. Heiße Mischungen vor hohen Stufen auf unter 60 °C abkühlen lassen."};
  case "emulsify":return new String[]{"Öl und wässrige Zutaten zu einem gleichmäßigen Dressing verbinden.","Grundzutaten nach Rezept in den Mixtopf geben. Dieses Setup verwendet das Messer ohne Heizung.","Mit 1 Minute auf Stufe 3 beginnen. Öl langsam und auf dem vom Rezept vorgesehenen Weg zugeben.","Bei Stillstand prüfen: Das Dressing soll gleichmäßig sein und keine sichtbare Ölschicht bilden."};
  case "warm":return new String[]{"Bereits zubereitete Speisen erwärmen. Wasser erhitzen ist für klares Wasser gedacht.","Suppe oder Sauce mit ausreichend Flüssigkeit einfüllen und Deckel schließen. Ohne Messerabdeckung arbeiten.","Temperatur zwischen 35 und 90 °C und Linkslauf-Stufe 0,5, 1 oder 1,5 wählen. Für empfindliche Stücke mit 0,5 beginnen.","Bei gewünschter Wärme selbst stoppen. Das Erreichen des Temperaturziels beendet den Lauf nicht; spätestens nach 120 Minuten endet er aus Sicherheitsgründen. Die Anzeige misst am Topf, nicht im Kern der Speise."};
  case "lidless":return new String[]{"Saucen im offenen Mixtopf köcheln und reduzieren.","Zutaten mit ausreichend Flüssigkeit einfüllen. Der Lauf bleibt auf 100 °C und Rühren bis Stufe 3 begrenzt.","Mit 10 Minuten bei 95 °C und Rühren 1 beginnen. Weil mehr Flüssigkeit verdampft, die gewünschte Saucendicke regelmäßig kontrollieren.","Vor Zugaben oder Umrühren stoppen und den Messerstillstand abwarten. Hände und Spatel während des Laufs aus dem Topf halten."};
  case "chop":return new String[]{"Zwiebeln und Gemüse in erkennbare kleine Stücke zerteilen.","Zwiebeln schälen und vierteln; anderes Gemüse ähnlich groß teilen. Messer einsetzen, Zutaten einfüllen und Deckel schließen.","Mit 6 Sekunden auf Messerstufe 6 beginnen. Nach jedem kurzen Lauf die Feinheit prüfen; weniger Zeit ergibt gröbere Stücke.","Bei Stillstand mit dem Spatel nach unten schieben. Kein Rühraufsatz bei hohen Stufen; heiße Zutaten vorher auf unter 60 °C abkühlen lassen."};
  case "puree":return new String[]{"Gegartes Gemüse mit Flüssigkeit cremig pürieren.","Zutaten weich garen und ausreichend Flüssigkeit zugeben. Vor hohen Stufen den Topf und den gesamten Inhalt auf unter 60 °C abkühlen lassen.","Rühraufsatz entfernen, Deckel schließen: mit 30 Sekunden und Zielstufe 6 ohne Heizung beginnen. Das Messer läuft langsam von Stufe 1 hoch.","Bei Stillstand prüfen. Für ein dünneres Püree Flüssigkeit ergänzen und kurz weiterverarbeiten."};
  case "slow":return new String[]{"Schmorgerichte über 1 bis 8 Stunden schonend garen.","Fleisch bei Bedarf vorher anbraten. Danach Zutaten und so viel Sauce oder Garflüssigkeit zugeben, dass das Gargut nach Rezept bedeckt ist. Die Füllmarkierung beachten.","Messerabdeckung bei Stillstand einsetzen und Deckel schließen. Stunden, Minuten und 37 bis 98 °C einstellen; rückwärts 0,5 mit kurzen Pausen ist fest vorgegeben.","Bei hohen Temperaturen vorsichtig mit heißem Dampf umgehen. Nach dem Lauf Zartheit und bei Fleisch die sichere Kerntemperatur nach Rezept prüfen; die Topfanzeige misst keine Kerntemperatur."};
  case "rice":return new String[]{"Reis im kleinen Gareinsatz innerhalb des Mixtopfs garen.","Reis nach Packungsangabe waschen, in den Gareinsatz geben und den Einsatz korrekt in den Mixtopf setzen.","Wasser aus einem passenden Geräte-Rezept für Reissorte und Menge übernehmen; das Quellverhältnis für Reis direkt im Topf nicht auf den Gareinsatz übertragen.","25 Minuten für Weißreis und 40 Minuten für Vollkorn sind unkalibrierte Richtwerte einschließlich Aufheizen. Danach die Körner prüfen und den heißen Einsatz mit dem vorgesehenen Hilfsmittel herausheben."};
  case "steam":return new String[]{"Brokkoli, Blumenkohl und Möhren im großen Dampfgaraufsatz garen.","Gemüse ähnlich groß schneiden. Wasser nach einem passenden Geräte-Rezept in den Mixtopf füllen.","Breiten Aufsatz korrekt aufsetzen. Gemüse locker auf Boden und Einlegeboden verteilen, Dampföffnungen freilassen und Deckel schließen.","Garzeit nach Stückgröße und Menge wählen. Nach dem Programm die Bissfestigkeit prüfen und den heißen Deckel vom Körper weg öffnen."};
  case "eggs":return new String[]{"Eier direkt im Mixtopf garen, ohne Gareinsatz.","Unbeschädigte Eier vorsichtig direkt in den Mixtopf legen. Für diesen Ablauf muss das Messer stillstehen.","Eieranzahl und Gargrad vormerken. Größe und Ausgangstemperatur beeinflussen das Ergebnis; daraus wird hier noch keine automatische Zeit berechnet.","Ein vollständiger Ablauf braucht eine geprüfte Wassermenge und Garzeit. Eier anschließend mit einem geeigneten Hilfsmittel entnehmen."};
  case "dough":return new String[]{"Teig mit wechselnden Messerbewegungen kneten.","Zutaten in der Reihenfolge eines passenden Geräte-Rezepts zugeben. Die für den konkreten Teig erlaubte Menge einhalten.","Schwere Brot- und Pizzateige brauchen andere Abläufe als weiche Rührteige. Gleichmäßiges Rühren ersetzt das Knetprogramm nicht.","Nach dem vollständigen Programm eine gleichmäßige, zum Rezept passende Teigstruktur prüfen."};
  case "grind":return new String[]{"Trockene Nüsse oder Gewürze fein und mehlartig mahlen.","Nur dafür geeignete Zutaten und Mengen verwenden. Topf und Messer müssen trocken sein; keinen Rühraufsatz einsetzen.","Mahlen erzeugt feines Pulver; Zerkleinern lässt gröbere Stücke zurück. Ölhaltige Nüsse werden bei zu langer Verarbeitung zu Mus.","Nach jedem vorgesehenen Intervall den Stillstand abwarten und die Feinheit prüfen."};
  case "ice":return new String[]{"Eiswürfel zu kleineren Crushed-Ice-Stücken verarbeiten.","Nur laut Geräteanleitung geeignete Eisgrößen und Mengen verwenden. Messer einsetzen, keinen Rühraufsatz verwenden und Deckel schließen.","Das Eisprogramm braucht kurze, zur Belastung passende Abschnitte. Dafür wird hier noch kein ungeprüfter Dauerlauf angeboten.","Nach dem Stillstand prüfen, ob die gewünschte Stückgröße erreicht ist."};
  case "sousvide":return new String[]{"Verschlossene Lebensmittel in einem kontrollierten Wasserbad garen.","Geeignete hitzebeständige Beutel und freigegebenes Zubehör verwenden. Die flache Messerabdeckung schützt vor Kontakt mit dem Messer. Ihre Grenzen sind Stufe 1 und 100 °C bei ausreichend Flüssigkeit; sie ersetzt nicht die Prüfung des Wasserbadablaufs.","Zeit und Temperatur aus einem geprüften Rezept für Lebensmittel und Dicke übernehmen. Die Solltemperatur allein bestätigt keine gleichmäßige Wassertemperatur.","Beutel und Wasserstand während eines freigegebenen Ablaufs wie vorgesehen kontrollieren. Der geprüfte Ablauf ist hier noch nicht verfügbar."};
  case "ferment":return new String[]{"Joghurt oder andere geeignete Ansätze über längere Zeit temperieren.","Mit sauberen Gefäßen und einem konkreten Rezept arbeiten. Milch, Kultur und Mengen in der dort angegebenen Reihenfolge vorbereiten.","Temperatur und Dauer müssen zur Kultur passen. Ein Zwei-Stunden-Heizlauf ersetzt kein mehrstündiges Fermentationsprogramm.","Das Ergebnis nach Rezept prüfen und anschließend wie vorgesehen kühlen und lagern."};
  case "scale":return new String[]{"Zutaten direkt im Mixtopf wiegen.","Mixtopf einsetzen und Maschine auf eine feste ebene Fläche stellen.","Vor jeder neuen Zutat Tara wählen. Langsam zugeben, ohne Topf oder Maschine zu berühren.","Eine stabile Anzeige abwarten und Gesamtlast sowie Füllmarkierung beachten."};
  case "thicken":return new String[]{"Saucen und Cremes unter langsamer Messerbewegung binden. Nur die Bindemitteltemperatur wird gewählt.","Zutaten nach Rezept in den Mixtopf geben. Stärke vorher mit etwas kalter Rezeptflüssigkeit glatt rühren. Empfindliche Stücke vorher herausnehmen.","Für Ei 80 °C mit fest 10 Minuten wählen, etwa für Hollandaise, Béarnaise, Vanillesoße oder Curd. Für Mehl oder Stärke 100 °C mit fest 12 Minuten wählen. Intern läuft das Messer vorwärts auf Stufe 2.","Die Konsistenz hängt von Zutaten und Mengen ab. Nach dem Lauf bei Messerstillstand prüfen; Creme kann beim Abkühlen nachdicken. Die Maschine beendet nach der festgelegten Zeit, nicht nach erkannter Bindung."};
  case "turbo":return new String[]{"Mit einem kurzen Messerimpuls zerkleinern.","Nur geeignete kalte Zutaten in einer laut Geräte-Rezept passenden Menge verwenden. Messerabdeckung und Rühraufsatz entfernen; nur das Messer bleibt eingesetzt. Deckel schließen und Messbecher einsetzen.","Mit 1 Sekunde auf Stufe 10 ohne Heizung beginnen. Wählbar sind 1 oder 2 Sekunden und die Stufen 10, 11 und 12. Vor dem Start muss der Topf unter 60 °C liegen.","Jeder Start führt genau einen zeitbegrenzten Lauf aus. Danach den Stillstand abwarten und die Feinheit prüfen. Nur bei Bedarf einen weiteren Impuls starten; nicht automatisch wiederholen."};
  case "caramel":return new String[]{"Zucker gezielt zu bernsteinfarbenem Karamell verarbeiten. Der passende Geräteablauf wird noch vorbereitet.","Ein Karamellrezept muss Zuckerart, Menge, Wasserzugabe und den gesamten Temperaturverlauf auf diese Maschine abstimmen. Dafür gibt es hier noch keine freigegebenen Startwerte.","Messerabdeckung und Aufschlagbesen sind für diesen Hochtemperaturablauf nicht vorgesehen. Ein frei gewählter Anbraten-Lauf ersetzt die Prüfung nicht.","Nach einem künftig freigegebenen Ablauf heißes Karamell wie im Rezept weiterverarbeiten und vor dem Probieren abkühlen lassen."};
  default:throw new IllegalArgumentException("Unknown function: "+id);
 }}
 private FunctionGuidance(){}
}
